package dev.reliefgrid.service;
import dev.reliefgrid.engine.AllocationEngine; import dev.reliefgrid.model.*;import dev.reliefgrid.repo.*;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.transaction.support.TransactionSynchronization; import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.util.*; import java.util.function.Function; import java.util.stream.*;
@Service public class AllocationService {
 private final ShelterRepository shelters;private final ResourceStockRepository stocks;private final CitizenRequestRepository requests;private final VolunteerRepository volunteers;private final AllocationPlanRepository plans;private final AssignmentRepository assignments;private final AuditLogRepository audits;private final Events events;
 public AllocationService(ShelterRepository sh,ResourceStockRepository st,CitizenRequestRepository rq,VolunteerRepository v,AllocationPlanRepository p,AssignmentRepository a,AuditLogRepository l,Events e){shelters=sh;stocks=st;requests=rq;volunteers=v;plans=p;assignments=a;audits=l;events=e;}
 public AllocationEngine.Input input(){return new AllocationEngine.Input(shelters.findAll().stream().map(s->new AllocationEngine.Place(s.id,s.lat,s.lon,s.underserved)).toList(),stocks.findAll().stream().map(s->new AllocationEngine.Stock(s.id,s.shelter.id,s.category,s.available)).toList(),requests.findAll().stream().filter(r->r.quantity>r.fulfilled).map(r->new AllocationEngine.Demand(r.id,r.shelter.id,r.category,r.quantity-r.fulfilled,r.urgency,r.createdAt.toEpochMilli()*1000+r.id)).toList(),volunteers.findAll().stream().map(v->new AllocationEngine.Carrier(v.id,v.shelter.id,Math.max(0,v.capacity-v.committed),v.active)).toList());}
 @Transactional public AllocationPlan propose(){AllocationEngine.Result result=AllocationEngine.optimized(input());AllocationPlan plan=plans.save(new AllocationPlan("PENDING"));Map<Long,CitizenRequest> rq=requests.findAll().stream().collect(Collectors.toMap(x->x.id,Function.identity()));Map<Long,ResourceStock> st=stocks.findAll().stream().collect(Collectors.toMap(x->x.id,Function.identity()));Map<Long,Volunteer> vs=volunteers.findAll().stream().collect(Collectors.toMap(x->x.id,Function.identity()));for(var pick:result.picks()){Assignment a=assignments.save(new Assignment(plan,rq.get(pick.demandId()),st.get(pick.stockId()),vs.get(pick.carrierId()),pick.quantity(),pick.distanceKm(),pick.explanation()));audits.save(new AuditLog("ALLOCATION_RECOMMENDED","plan="+plan.id+" assignment="+a.id+" "+pick.explanation()));}audits.save(new AuditLog("PLAN_PROPOSED","plan="+plan.id+" units="+result.allocated()+" timeNs="+result.nanos()));afterCommit("plan");return plan;}
 @Transactional public AllocationPlan reject(long id){AllocationPlan p=plans.locked(id).orElseThrow(()->new IllegalArgumentException("Plan not found"));if(!"PENDING".equals(p.status))throw new IllegalStateException("Plan already finalized");p.status="REJECTED";assignments.findByPlanId(id).forEach(a->a.status="REJECTED");audits.save(new AuditLog("PLAN_REJECTED","plan="+id));afterCommit("plan");return p;}
 @Transactional public AllocationPlan approve(long id){AllocationPlan p=plans.locked(id).orElseThrow(()->new IllegalArgumentException("Plan not found"));if(!"PENDING".equals(p.status))throw new IllegalStateException("Plan already finalized");List<Assignment> lines=assignments.findByPlanId(id);Map<Long,Integer> byStock=new TreeMap<>(),byRequest=new TreeMap<>(),byVolunteer=new TreeMap<>();for(Assignment a:lines){byStock.merge(a.stock.id,a.quantity,Integer::sum);byRequest.merge(a.request.id,a.quantity,Integer::sum);byVolunteer.merge(a.volunteer.id,a.quantity,Integer::sum);if(a.stock.category!=a.request.category)throw new IllegalStateException("Category mismatch");}
 // Deterministic lock order for deadlock avoidance; any shortage rolls back the whole approval.
 for(var entry:byStock.entrySet()){ResourceStock s=stocks.locked(entry.getKey()).orElseThrow();if(s.available<entry.getValue())throw new IllegalStateException("Inventory changed: stock "+s.id+" insufficient");s.available-=entry.getValue();s.reserved+=entry.getValue();}
 for(var entry:byVolunteer.entrySet()){Volunteer v=volunteers.locked(entry.getKey()).orElseThrow();if(!v.active||v.capacity-v.committed<entry.getValue())throw new IllegalStateException("Volunteer capacity changed: "+v.id);v.committed+=entry.getValue();}
 for(var entry:byRequest.entrySet()){CitizenRequest r=requests.locked(entry.getKey()).orElseThrow();if(r.quantity-r.fulfilled<entry.getValue())throw new IllegalStateException("Demand changed: request "+r.id);r.fulfilled+=entry.getValue();}
 for(Assignment a:lines){a.status="RESERVED";audits.save(new AuditLog("ASSIGNMENT_RESERVED","plan="+id+" assignment="+a.id+" request="+a.request.id+" stock="+a.stock.id+" volunteer="+a.volunteer.id+" quantity="+a.quantity));}
 p.status="APPROVED";audits.save(new AuditLog("PLAN_APPROVED","plan="+id));afterCommit("plan");return p;}
 @Transactional public Assignment deliver(long id){Assignment a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(!"RESERVED".equals(a.status))throw new IllegalStateException("Assignment not reserved");ResourceStock s=stocks.locked(a.stock.id).orElseThrow();if(s.reserved<a.quantity)throw new IllegalStateException("Reserved stock inconsistent");s.reserved-=a.quantity;Volunteer v=volunteers.locked(a.volunteer.id).orElseThrow();if(v.committed<a.quantity)throw new IllegalStateException("Volunteer commitment inconsistent");v.committed-=a.quantity;a.status="DELIVERED";audits.save(new AuditLog("ASSIGNMENT_DELIVERED","assignment="+id));afterCommit("assignment");return a;}
 private void afterCommit(String event){TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){events.changed(event);}});}
 public List<AllocationPlan> plans(){return plans.findAll();} public List<Assignment> assignments(){return assignments.findAll();} public List<AuditLog> audits(){return audits.findAll();}
 public Map<String,Object> compare(){AllocationEngine.Input in=input();AllocationEngine.Result base=AllocationEngine.baseline(in),opt=AllocationEngine.optimized(in);return Map.of("baseline",metric(in,base),"optimized",metric(in,opt),"scenario","current database state; deterministic algorithms");}
 private Map<String,Object> metric(AllocationEngine.Input in,AllocationEngine.Result r){Map<Long,Integer> served=new HashMap<>();r.picks().forEach(p->served.merge(p.demandId(),p.quantity(),Integer::sum));int total=in.demands().stream().mapToInt(AllocationEngine.Demand::quantity).sum(),high=in.demands().stream().filter(d->d.urgency()>=4).mapToInt(AllocationEngine.Demand::quantity).sum(),highServed=in.demands().stream().filter(d->d.urgency()>=4).mapToInt(d->served.getOrDefault(d.id(),0)).sum();Map<Long,Integer> perShelter=new HashMap<>(),needShelter=new HashMap<>();for(var d:in.demands()){perShelter.merge(d.shelterId(),served.getOrDefault(d.id(),0),Integer::sum);needShelter.merge(d.shelterId(),d.quantity(),Integer::sum);}double[] ratios=needShelter.entrySet().stream().mapToDouble(e->(double)perShelter.getOrDefault(e.getKey(),0)/e.getValue()).toArray();double avg=Arrays.stream(ratios).average().orElse(0),variance=Arrays.stream(ratios).map(x->(x-avg)*(x-avg)).average().orElse(0);return Map.of("allocated",r.allocated(),"unmetDemand",total-r.allocated(),"highPriorityFulfillmentPct",high==0?100:100.0*highServed/high,"fairnessStdDev",Math.sqrt(variance),"assignmentKmUnits",r.distance(),"inventoryViolations",validate(in,r),"duplicateAssignments",r.picks().size()-(int)r.picks().stream().map(p->p.stockId()+"-"+p.demandId()+"-"+p.carrierId()).distinct().count(),"computationMs",r.nanos()/1e6);}
 private int validate(AllocationEngine.Input in,AllocationEngine.Result r){Map<Long,Integer> s=new HashMap<>(),v=new HashMap<>(),d=new HashMap<>();r.picks().forEach(p->{s.merge(p.stockId(),p.quantity(),Integer::sum);v.merge(p.carrierId(),p.quantity(),Integer::sum);d.merge(p.demandId(),p.quantity(),Integer::sum);});int violations=0;for(var x:in.stocks())if(s.getOrDefault(x.id(),0)>x.quantity())violations++;for(var x:in.carriers())if(v.getOrDefault(x.id(),0)>x.capacity())violations++;for(var x:in.demands())if(d.getOrDefault(x.id(),0)>x.quantity())violations++;return violations;}
}
